mapper.select:
SELECT  FROM im_webhook_subscription
 WHERE owner_type = 'CLUB' AND owner_id = #{ownerId} AND channel_id = #{channelId} AND deleted = 0
 AND id < #{beforeId}
 ORDER BY id DESC
 LIMIT #{limit}

SELECT  FROM im_webhook_delivery
 WHERE subscription_id = #{subscriptionId}
 AND state = #{state}
 AND id < #{beforeId}
 ORDER BY id DESC
 LIMIT #{limit}

SELECT  FROM im_webhook_endpoint
 WHERE owner_type = 'CLUB' AND owner_id = #{ownerId} AND channel_id = #{channelId} AND deleted = 0
 AND id < #{beforeId}
 ORDER BY id DESC
 LIMIT #{limit}

SELECT id, endpoint_id AS endpointId, result, reason, message_id AS messageId, request_hash AS requestHash, nonce,
       sender_type AS senderType, webhook_id AS webhookId, original_message_stored AS originalMessageStored,
       create_time AS createTime
  FROM im_webhook_inbound_log
 WHERE endpoint_id = #{endpointId}
 AND result = #{result}
 AND id < #{beforeId}
 ORDER BY id DESC
 LIMIT #{limit}
